			classifyDurableIssuanceTerminalSuppression({
100→				candidate: expected,
				observation,
				priorLineage: { exhausted: false, next: 0 },
				scope: SCOPE,
			});
			return { code: "SUCCESS", exposedKeys: [] };
		} catch (error) {
			return exposed(error);
		}
	} finally {
110→		await store.close();
	}
}

